DO $test$
DECLARE boss uuid; clerk uuid; sales uuid:=gen_random_uuid(); money uuid:=gen_random_uuid(); b uuid; company uuid; id uuid:=gen_random_uuid(); p jsonb; x jsonb; key text;
BEGIN
 SELECT employee INTO boss FROM contract_private.handles WHERE username='admin';
 SELECT employee INTO clerk FROM contract_private.handles WHERE username='newuser';
 SELECT br.id,co.id INTO b,company FROM app.branches br JOIN app.companies co ON co.id=br.company_id WHERE co.code='bakheet' AND br.name='الدورة';
 INSERT INTO auth.users(id,email) VALUES(sales,'sales@dummy.invalid'),(money,'money@dummy.invalid');
 p:=jsonb_build_object('company','bakheet','companies',jsonb_build_array('bakheet','imad'),'target',sales,'username','sales','name','مبيعات','department','sales','role','employee','active',true,'branchRoles',jsonb_build_object(b,'employee'));
 PERFORM public.contract_staff_assignment(boss,'create',p);
 ASSERT jsonb_array_length(public.contract_portal(sales,'session','{}')->'companies')=2;
 PERFORM public.contract_staff_assignment(boss,'create',p||jsonb_build_object('companies',jsonb_build_array('bakheet'),'target',money,'username','finance','department','finance'));
 ASSERT jsonb_array_length(public.contract_portal(money,'session','{}')->'companies')=1;
 p:=jsonb_build_object('company','bakheet','branch','الدورة','id',id,'version',0,'data',jsonb_build_object('contractType','cash','buyer','زبون اختبار','total','300'));
 x:=public.sales_forms(sales,'form_save',p);ASSERT x->>'version'='1';
 ASSERT public.sales_forms(boss,'forms_list',p)='[]' AND public.sales_forms(money,'forms_list',p)='[]';
 BEGIN PERFORM public.sales_forms(boss,'form_read',p);RAISE EXCEPTION 'admin read another draft';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_publish',p);RAISE EXCEPTION 'stale publication';EXCEPTION WHEN serialization_failure THEN NULL;END;
 x:=public.sales_forms(sales,'form_publish',p||'{"version":1}');ASSERT x->>'version'='2';
 ASSERT jsonb_array_length(public.sales_forms(money,'forms_list',p))=1;
 BEGIN PERFORM public.sales_forms(money,'form_convert',p||'{"version":2}');RAISE EXCEPTION 'finance converted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_approve',p||'{"version":2}');RAISE EXCEPTION 'sales approved';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(boss,'form_approve',p||'{"version":2}');
 x:=public.sales_forms(clerk,'form_convert',p||'{"version":3}');key:=x->>'record';
 ASSERT NOT(public.sales_forms(money,'form_read',p)?'contract_key');
 ASSERT key IS NOT NULL AND public.sales_forms(clerk,'form_convert',p)->>'record'=key;
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.contract_archive(clerk,'list',p)) e WHERE e->>'record'=key AND e#>>'{draft,buyer}'='زبون اختبار');
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.contract_archive(boss,'list',p)) e WHERE e->>'record'=key);
 BEGIN PERFORM public.contract_number(boss,jsonb_build_object('company','bakheet','branch','الدورة','record',key,'mode','claim'));RAISE EXCEPTION 'private reservation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.contract_archive(sales,'list',p);RAISE EXCEPTION 'sales contract archive';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.contract_archive(money,'download',p);RAISE EXCEPTION 'finance download';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(clerk,'move_contract',p||jsonb_build_object('destination','imad','record',key,'version',1));RAISE EXCEPTION 'unassigned company';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT public.sales_forms(sales,'forms_list',p||'{"company":"imad"}')='[]';
 SELECT public.contract_portal(boss,'members','{"company":"bakheet"}') INTO x;
 SELECT e INTO x FROM jsonb_array_elements(x) e WHERE e->>'id'=clerk::text;
 PERFORM public.contract_staff_assignment(boss,'update',jsonb_build_object('company','bakheet','companies',jsonb_build_array('bakheet','imad'),'target',clerk,'username','newuser','name','كاتب','department','contracts','role','employee','active',true,'version',x->'version','branchRoles',jsonb_build_object(b,'employee')));
 PERFORM public.sales_forms(clerk,'move_contract',p||jsonb_build_object('destination','imad','record',key,'version',1));
 ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(public.contract_archive(clerk,'list','{"company":"imad"}')) e WHERE e->>'record'=key AND e#>>'{draft,companyId}'='imad');
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.contract_archive(clerk,'list','{"company":"bakheet"}')) e WHERE e->>'record'=key);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',money)::text,true);
 ASSERT NOT contract_private.read_branch(company,b);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',clerk)::text,true);
 ASSERT contract_private.read_branch(company,b);
 ASSERT NOT has_function_privilege('authenticated','public.sales_forms(uuid,text,jsonb)','EXECUTE');
END $test$;
